288	int rb_delete(rbtree_t *t, const char *key) {
289	    rb_node_t *z = t->root;
290	    while (z != NULL) {
291	        int cmp = strcmp(key, z->key);
292	        if (cmp == 0) {
293	            break;
294	        }
295	        z = (cmp < 0) ? z->left : z->right;
296	    }
297	    if (z == NULL) {
298	        return -1;
299	    }
300	
301	    rb_node_t *y = z;
302	    rb_color_t y_original_color = y->color;
303	    rb_node_t *x;
304	    rb_node_t *x_parent;
305	
306	    if (z->left == NULL) {
307	        x = z->right;
308	        x_parent = z->parent;
309	        transplant(t, z, z->right);
310	    } else if (z->right == NULL) {
311	        x = z->left;
312	        x_parent = z->parent;
313	        transplant(t, z, z->left);
314	    } else {
315	        y = subtree_min(z->right);
316	        y_original_color = y->color;
317	        x = y->right;
318	        if (y->parent == z) {
319	            x_parent = y;
320	        } else {
321	            x_parent = y->parent;
322	            transplant(t, y, y->right);
323	            y->right = z->right;
324	            y->right->parent = y;
325	        }
326	        transplant(t, z, y);
327	        y->left = z->left;
328	        y->left->parent = y;
329	        y->color = z->color;
330	    }
331	
332	    rb_free(z->key);
333	    if (t->value_free != NULL) {
334	        t->value_free(z->value);
335	    }
336	    rb_free(z);
337	    t->size--;
338	
339	    if (y_original_color == RB_BLACK) {
340	        delete_fixup(t, x, x_parent);
