349	static void foreach_subtree(const rb_node_t *node,
350	                            void (*fn)(const char *key, void *value, void *ctx),
351	                            void *ctx) {
352	    if (node == NULL) {
353	        return;
354	    }
355	    foreach_subtree(node->left, fn, ctx);
356	    fn(node->key, node->value, ctx);
357	    foreach_subtree(node->right, fn, ctx);
358	}
