366	/* Returns the black-height of node's subtree (NIL counts as black height
367	 * 0), or -1 if a red node has a red child or the two subtrees disagree on
368	 * black-height. */
369	static int check_black_height(const rb_node_t *node) {
370	    if (node == NULL) {
371	        return 0;
372	    }
373	    if (node->color == RB_RED &&
374	        (node_color(node->left) == RB_RED || node_color(node->right) == RB_RED)) {
375	        return -1;
376	    }
377	    int left_bh = check_black_height(node->left);
378	    if (left_bh < 0) {
379	        return -1;
380	    }
381	    int right_bh = check_black_height(node->right);
382	    if (right_bh < 0 || left_bh != right_bh) {
383	        return -1;
384	    }
385	    return left_bh + (node->color == RB_BLACK ? 1 : 0);
386	}
387	
388	/* In-order walk checking strict increase under strcmp. *last tracks the
389	 * most recently visited key (NULL before the first). */
390	static int check_strictly_increasing(const rb_node_t *node, const char **last) {
391	    if (node == NULL) {
392	        return 1;
393	    }
394	    if (!check_strictly_increasing(node->left, last)) {
395	        return 0;
396	    }
397	    if (*last != NULL && strcmp(*last, node->key) >= 0) {
398	        return 0;
399	    }
400	    *last = node->key;
401	    return check_strictly_increasing(node->right, last);
402	}
403	
404	static size_t count_subtree(const rb_node_t *node) {
405	    if (node == NULL) {
406	        return 0;
407	    }
408	    return 1 + count_subtree(node->left) + count_subtree(node->right);
409	}
410	
411	int rb_validate(const rbtree_t *t) {
412	    if (node_color(t->root) != RB_BLACK) {
413	        return -1;
414	    }
415	    if (check_black_height(t->root) < 0) {
416	        return -1;
417	    }
418	    const char *last = NULL;
419	    if (!check_strictly_increasing(t->root, &last)) {
420	        return -1;
421	    }
422	    if (count_subtree(t->root) != t->size) {
423	        return -1;
424	    }
425	    return 0;
426	}
427	
428	static void destroy_subtree(rb_node_t *node, rb_value_free_fn value_free) {
429	    if (node == NULL) {
430	        return;
431	    }
432	    destroy_subtree(node->left, value_free);
433	    destroy_subtree(node->right, value_free);
434	    rb_free(node->key);
435	    if (value_free != NULL) {
436	        value_free(node->value);
437	    }
438	    rb_free(node);
439	}
440	
441	void rb_destroy(rbtree_t *t) {
442	    if (t == NULL) {
443	        return;
444	    }
445	    destroy_subtree(t->root, t->value_free);
446	    rb_free(t);
447	}
